&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;singleLevel&amp;quot;}&quot; data-aria-posinset=&quot;13&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Ervaring met het afwegen en kiezen tussen app-, portal-, workflow- en agent-patronen (Power Apps, Power &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Automate&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;, Power Pages, &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Copilot&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt; Studio).&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
