&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;What This Role Is Not&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A community or social media management role&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A pure performance marketing or media buying role&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A traditional brand campaign role focused only on large launches&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;An agency coordination role without creative ownership&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A culture of growth&amp;nbsp;&amp;nbsp; &lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;With over 50 nationalities represented,&amp;nbsp;we’re&amp;nbsp;proud to welcome people of all backgrounds to our growing community, and&amp;nbsp;we’re&amp;nbsp;always finding new ways to help people feel welcomed and included. Here,&amp;nbsp;you’ll&amp;nbsp;have the tools,&amp;nbsp;training&amp;nbsp;and support you need to work in a way that suits you, learn new&amp;nbsp;skills&amp;nbsp;and reach your potential.&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;For a career where you can drive our business and shape your future, apply now.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;<p>Find more <a href="https://www.arbeitnow.com/english-speaking-jobs">English Speaking Jobs in Germany</a> on Arbeitnow</a>

&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;At &lt;strong&gt;AutoScout24&lt;/strong&gt;, our Data Platform Engineering team builds and operates the AWS-based platform that enables teams across the company to work with data independently. Built around Data Mesh principles, it provides the infrastructure, self-service tooling, and governance that allow domain teams to own and manage their data products.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:60,&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;none&quot;&gt;As &lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Engineering Manager&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;, you&#39;ll lead the team responsible for developing and operating this platform. The role combines people leadership with strong technical involvement, from architecture and complex engineering problems to reliability, performance, and cost optimization.&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;none&quot;&gt;We&#39;re also making AI a native part of how our Data Engineering organization works and how people use our platform. This includes bringing AI directly into the daily workflows of Data Engineers and Analytics Engineers, as well as making the platform more intelligent, easier to use, and more accessible to business users.&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:60,&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;What you&#39;ll do&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Build a team that takes ownership, makes sound technical decisions, and delivers independently.&lt;/span&gt; &lt;/li&gt;
